def group_anagrams(words):
    groups = {}
    order = []
    for word in words:
        counts = [0] * 26
        for ch in word:
            counts[ord(ch) - ord('a')] += 1
        key = tuple(counts)
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(word)
    return [groups[key] for key in order]

