def longest_consecutive(nums):
    values = set(nums)
    best = 0
    for x in values:
        # 只从连续段的起点开始扩展
        if x - 1 not in values:
            length = 1
            while x + length in values:
                length += 1
            if length > best:
                best = length
    return best

coding.alternativeCode:
def longest_consecutive(nums):
    if not nums:
        return 0
    ordered = sorted(set(nums))
    best = 1
    current = 1
    for i in range(1, len(ordered)):
        if ordered[i] == ordered[i - 1] + 1:
            current += 1
        else:
            current = 1
        if current > best:
            best = current
    return best

