def pair_sum_values(nums, target):
    ordered = sorted(nums)
    left, right = 0, len(ordered) - 1
    result = []
    while left < right:
        total = ordered[left] + ordered[right]
        if total == target:
            result.append([ordered[left], ordered[right]])
            left += 1
            right -= 1
            while left < right and ordered[left] == ordered[left - 1]:
                left += 1
            while left < right and ordered[right] == ordered[right + 1]:
                right -= 1
        elif total < target:
            left += 1
        else:
            right -= 1
    return result
